import os, sys, json
cmd, args = sys.argv[1], sys.argv[2:]
if cmd == "st":
    for p in args:
        try:
            s = os.lstat(p); print("%s %d:%d" % (p, s.st_uid, s.st_gid))
        except FileNotFoundError:
            print(p, "absent")
elif cmd == "save":
    tag, paths = args[0], args[1:]
    json.dump({p: os.lstat(p).st_ctime_ns for p in paths}, open(tag + ".ctime", "w"))
elif cmd == "chg":
    old = json.load(open(args[0] + ".ctime"))
    for p in args[1:]:
        print(p, "advanced" if os.lstat(p).st_ctime_ns > old[p] else "unchanged")
elif cmd == "mk":
    for p in args:
        open(p, "w").write("x")
elif cmd == "link":
    os.symlink(args[0], args[1])
elif cmd == "fifo":
    os.mkfifo(args[0])

